"use strict";(self.webpackChunkuxcam=self.webpackChunkuxcam||[]).push([[3679],{8283:function(e,a,t){t.r(a),t.d(a,{Head:function(){return c},default:function(){return l}});var s=t(96540),n=t(86997),r=t(54727);var i={seo:{title:"UXCam Case study | Carrefour Banco",description:"UXCam is an analytics solution for mobile apps, web apps and websites. Session Replay, Heatmaps, Funnel Analytics and Quantitative Analytics make UXCam a complete enterprise analytics solution for deeply understanding user behavior.",image:"https://images.ctfassets.net/vv1yxl437u7d/3Mn0AbpUmb4aFxUXNgpzY6/77b23638bee2a4c3cc29e6336ace2e1f/metaimageNEW.png"},hero:{industry:"Finance",title:"How Carrefour Banco reduced <span>rage taps by 50% with UXCam</span>",description:"Carrefour Banco (Banco de Servicios Financieros S.A.) is the entity that issues and markets Mi Carrefour Crédito and Mi Carrefour Prepaga cards, insurance and assistance services, and grants personal loans.\n\nAs part of the Carrefour Argentina Group, they add accessibility, proximity, and trust to their values. As a result, they are now the company most committed to financial inclusion, given that 35% of their customers use their card as their gateway to the financial world.",image:"/assets/images/case-study-carrefour-banco.webp"},stats:[{value:"> 1M installs",label:"on Google Play Store"},{value:"50% decrease",label:"of rage taps"},{value:"35% less abandonment",label:"on the affidavit screen"}],challenge:{title:"The challenge",backgroundImage:"https://images.ctfassets.net/vv1yxl437u7d/1Ov4GcUZwhwz6Gdk7x9TIS/ad9823ae58f2e2026f64d865f820a987/Vector.svg",paragraphs:["The Carrefour Banco team needed greater visibility into key flows within the Mi Carrefour Card app, especially in the onboarding process, but also to learn about usage patterns, screens, or flows where users abandon the app due to friction, but it was not always clear where or why.","With multiple versions in production, the team needed a way to understand actual user behavior beyond what QA tests or error logs could show. One example was users repeatedly tapping a calendar icon that was not interactive. This caused frustration and went unnoticed until the team reviewed the session replays."],quote:{text:"Sometimes we can't replicate what users report to us. UXCam helps us see what really happened, especially in atypical cases and in different versions of the app.",author:"Head of Digital Channels",role:""}},solution:{title:"The solution",backgroundImage:"https://images.ctfassets.net/vv1yxl437u7d/28xui9UzDyaFzt7EfaJuio/74b1070ae5cc420b5ac71c1dee040858/Vector.svg",paragraphs:["The team implemented UXCam to analyze actual user behavior and detect usability issues that internal testing had not identified.","By combining session replays with heatmaps, the team was able to analyze how users navigate the onboarding flow (from entering personal data to accepting contracts) and their subsequent interaction with the features of the app, such as QR payments and viewing savings. They could also compare behaviors between different versions in production, identify confusing interface elements, and correct design issues that slowed down the experience.","Additionally, the team was able to validate user feedback by linking it to actual behavior and evaluate the impact of design changes on interaction and abandonment."],quote:{text:"It's very helpful to see how users behave in a real context, not just in a test environment. We can see what they actually did.",author:"Head of Digital Channels",role:""}},whatsNext:{title:"The results",backgroundImage:"https://images.ctfassets.net/vv1yxl437u7d/Bc9n79vDsJLoV0HUy6g4j/db1b14e3e0162ced77ac4f4e7f6b5e6a/Path-7.svg",paragraphs:["UXCam gave the team a reliable way to detect problems, test hypotheses, and measure improvements, with notable results.","Rage taps decreased by 50% after removing a calendar icon that appeared interactive but was not. The affidavit screen was optimized, reducing gestures by 65% and abandonment by 35%.","Additionally, the contract acceptance process became 4 seconds faster in version 4.4.2 after unifying the steps for accepting contract terms."],quote:{text:"UXCam is very useful for validating issues that we wouldn't detect with QA alone. We can connect what users say with what actually happened in the session.",author:"Head of Digital Channels",role:""}}},o=t(17437);const c=()=>(0,o.Y)(s.Fragment,null,(0,o.Y)(r.A,{title:i.seo.title,description:i.seo.description,image:{file:{url:i.seo.image}}}),(0,o.Y)("link",{rel:"canonical",href:"https://uxcam.com/case-study/carrefour-banco/"}),(0,o.Y)("link",{rel:"alternate",hrefLang:"en",href:"https://uxcam.com/case-study/carrefour-banco/"}),(0,o.Y)("link",{rel:"alternate",hrefLang:"es",href:"https://uxcam.com/es/case-study/carrefour-banco/"}),(0,o.Y)("link",{rel:"alternate",hrefLang:"pt-BR",href:"https://uxcam.com/br/case-study/carrefour-banco/"}),(0,o.Y)("link",{rel:"alternate",hrefLang:"x-default",href:"https://uxcam.com/case-study/carrefour-banco/"}));var l=()=>(0,o.Y)(n.A,{data:i})}}]);